// Generated by flowapi from flowapi-sdk.yml and the API description. Do not edit: generate again.
//
// What the mock received of each kind of credential the client sends, and a call that needs none.

import assert from 'node:assert/strict'
import { after, before, test } from 'node:test'
import { AuthClient } from "auth-sdk"
import { mock } from '../mock/server.mjs'

let server
let client

before(async () => {
  server = await mock()
  client = new AuthClient({ baseURL: server.url, queryKey: 'test-credential', cookieKey: 'test-credential', basic: { username: 'user', password: 'pass' }, token: 'test-credential', oauth: { clientId: 'test-client', clientSecret: 'test-secret', tokenURL: `${server.url}/token` }, maxRetries: 0 })
})

after(() => server.close())

/** The request the mock answered last; `null` against a server of your own. */
const last = () => server.requests?.at(-1) ?? null

test("QueryKey: sent by checks.query_key", async () => {
  await client.checks.queryKey()
  const r = last()
  if (r === null) return
  assert.equal(new URL(r.url, 'http://mock.invalid').searchParams.get("api_key"), 'test-credential')
})

test("CookieKey: sent by checks.cookie", async () => {
  await client.checks.cookie()
  const r = last()
  if (r === null) return
  assert.ok((r.headers.cookie ?? '').split('; ').includes("session=test-credential"), r.headers.cookie)
})

test("Basic: sent by checks.basic", async () => {
  await client.checks.basic()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, `Basic ${Buffer.from('user:pass').toString('base64')}`)
})

test("Token: sent by checks.either", async () => {
  await client.checks.either()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, 'Bearer test-credential')
})

test("Oauth: sent by checks.oauth", async () => {
  await client.checks.oauth()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, 'Bearer mock-token')
  assert.ok(server.requests.some((q) => q.route === 'token'), 'the token was requested of the mock')
})

test("no credential: checks.open needs none", async () => {
  const none = new AuthClient({ baseURL: server.url, maxRetries: 0, queryKey: null, cookieKey: null, basic: null, token: null, oauth: null })
  await none.checks.open()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, undefined)
  assert.equal(new URL(r.url, 'http://mock.invalid').searchParams.has("api_key"), false)
  assert.ok(!(r.headers.cookie ?? '').split('; ').some((c) => c.startsWith("session=")))
})
